<p>Окремо закон дозволяє розірвати шлюб через РАЦС за заявою одного з подружжя, якщо інший визнаний безвісно відсутнім, недієздатним або засудженим до позбавлення волі на строк понад три роки. У таких випадках наявність дітей не перешкоджає адміністративному порядку.</p>
