        id: "s3",
        h2: "Документи та їх легалізація",
        html: `<p>Є деталь, яка регулярно стає неприємним відкриттям уже після процесу.</p>
<p><b>При судовому розлученні свідоцтво про розірвання шлюбу не видається.</b> Документом, що засвідчує факт розірвання шлюбу, є рішення суду, яке набрало законної сили. Шлюб припиняється з моменту набрання рішенням законної сили.</p>
<p>Звідси наслідок для використання за кордоном: <b>апостиль ставиться на самому рішенні суду з відміткою про набрання законної сили</b>, а не на свідоцтві — свідоцтва просто немає. Люди часто місяцями шукають, де «отримати свідоцтво про розлучення після суду», і втрачають час.</p>
<p>Базовий набір для позову про розірвання шлюбу з іноземцем:</p>
<ul>
<li>свідоцтво про шлюб (а якщо шлюб укладено за кордоном — із перекладом і легалізацією чи апостилем);</li>
<li>документи, що посвідчують особи подружжя; для іноземця — документ, що підтверджує законність перебування в Україні, якщо він тут перебуває;</li>
<li>документи про дітей, якщо вони є;</li>
<li>відомості про місце проживання відповідача за кордоном — для належного повідомлення;</li>
<li>квитанція про сплату судового збору.</li>
</ul>
<p>Якщо раніше хтось із подружжя вже був у шлюбі, додаються свідоцтво про розлучення, або рішення суду, якщо шлюб розривався в суді, або документ про зміну прізвища.</p>
<p><b>Повідомлення відповідача, який живе за кордоном,</b> — найдовша частина процесу й водночас найважливіша. Належне інформування є умовою визнання українського рішення за кордоном: рішення, ухвалене без нього, у більшості держав виконуватися не буде. Тому закладати на цей етап кілька місяців розумніше, ніж потім проходити все заново.</p>`,
