        html: `<p>Процедура дзеркальна, і її обсяг залежить від того, що саме у вас на руках.</p>
<p><b>Варіант перший — документ про розірвання шлюбу, оформлений за кордоном</b> адміністративним органом. Для використання в Україні потрібні апостиль або консульська легалізація плюс нотаріально засвідчений переклад. У частині випадків цього достатньо, і окрема судова процедура не потрібна.</p>
<p><b>Варіант другий — рішення іноземного суду</b>, щодо якого є спір або яке потрібне для подальших процедур. Тут застосовується механізм визнання іноземного рішення українським судом. За статтею 81 Закону «Про міжнародне приватне право» в Україні можуть бути визнані та виконані рішення іноземних судів у випадках, передбачених міжнародним договором, або за принципом взаємності.</p>
<p>Клопотання про визнання подається до суду за місцем проживання (перебування) або місцезнаходженням боржника чи його майна; у визнанні може бути відмовлено лише з підстав, передбачених відповідним договором. Серед багатосторонніх інструментів у цій сфері — Конвенція про визнання рішень про розлучення та про окреме проживання подружжя, прийнята Гаазькою конференцією з міжнародного приватного права у 1970 році, та двосторонні договори про правову допомогу.</p>
<p>Практична порада: перевіряти конфігурацію <b>до</b> початку дій, а не після. Від того, чи є між державами чинний договір і яке рішення у вас на руках, залежить, чи достатньо апостиля з перекладом, чи потрібна повна судова процедура визнання. Ці два шляхи відрізняються і за строками, і за вартістю в кілька разів.</p>
<p>Юристи практики <a href="/practices/family-law/">сімейного права LEGIUS</a> супроводжують розлучення з іноземним елементом — від визначення підсудності до легалізації результату. Про укладення шлюбу з іноземцем — у матеріалі про <a href="/blog/shlyub-z-inozemtsem/">шлюб з іноземцем</a>.</p>`,
