    h1: "Аліменти з іноземця",
    metaTitle: "Аліменти з іноземця: як стягнути за кордоном 2026",
    metaDescription:
      "Два шляхи стягнення аліментів з боржника за кордоном, Конвенція 2007 року, перелік документів для клопотання та розміри аліментів у 2026 році. LEGIUS.",
