        h2: "Крайній захід: передання дитини",
        html: `<p>Закон передбачає механізм на випадок, коли той із батьків, з ким проживає дитина, систематично не виконує рішення суду щодо спілкування.</p>
<p>У такому разі другий з батьків може звернутися до суду з вимогою про <b>передання дитини для проживання з ним</b>. Підстава — саме систематичне невиконання рішення, а не разові конфлікти.</p>
<p>Суд не застосовує цей механізм автоматично й оцінює його виключно крізь призму інтересів дитини. Зміна звичного середовища сама по собі є стресом, тому суд зважує, що зашкодить дитині більше — залишення в поточній ситуації чи переїзд.</p>
<p>Що потрібно для такої вимоги: тривала й документально підтверджена історія невиконання, матеріали виконавчого провадження, акти виконавця, звернення до поліції, висновок органу опіки, докази ваших умов для дитини.</p>
<p>Це найсильніший аргумент у всьому арсеналі — і саме тому фіксація кожного зірваного побачення має значення далеко за межами конкретного дня.</p>`,
