        html: `<p>Головне правило, яке не можна порушити: заяву про прийняття спадщини потрібно подати нотаріусу <strong>протягом шести місяців</strong> з дня відкриття спадщини (стаття 1270 ЦК України). Звертатися можна до будь-якого нотаріуса за місцем відкриття спадщини — державного чи приватного.</p>
<p>Виняток зроблено для тих, хто на момент смерті постійно проживав разом зі спадкодавцем: вони вважаються такими, що прийняли спадщину автоматично, якщо не заявили відмову (стаття 1268 ЦК України). Так само прийнятою вважається спадщина малолітніх, неповнолітніх і недієздатних спадкоємців. Усім іншим — навіть найближчим родичам, які жили окремо, — заява обов'язкова. Якщо строк уже спливає або спливнув, негайно читайте наш розбір <a href="/blog/propushchenyy-strok-spadshchyna/">що робити з пропущеним строком</a>.</p>`,
