        h2: "Нікчемний заповіт: порушення форми та посвідчення",
        html: `<p>Заповіт складається у письмовій формі, із зазначенням місця та часу складення, підписується особисто заповідачем і посвідчується нотаріусом або іншими уповноваженими законом особами. Порушення цих вимог робить заповіт нікчемним: він не породжує правових наслідків, і спадкування відбувається за законом.</p>
<p>Типові приклади з практики: заповіт підписала інша особа без дотримання спеціальної процедури, посвідчення здійснила неуповноважена особа, відсутні обов'язкові реквізити. У таких справах суд за позовом заінтересованої особи констатує нікчемність — це простіший шлях, ніж доводити вади волі, бо досліджується сам документ, а не стан заповідача.</p>`,
