        html: `<p>Часто мета — не скасувати заповіт повністю, а отримати належне попри нього. Малолітні, неповнолітні та повнолітні непрацездатні діти, непрацездатна вдова (вдівець) і непрацездатні батьки мають право на <strong>обов'язкову частку</strong> — половину того, що кожен із них отримав би при спадкуванні за законом (стаття 1241 ЦК України), незалежно від змісту заповіту.</p>
<p>Це право реалізується у нотаріуса без суду, якщо документи про непрацездатність чи вік у порядку. Суд потрібен лише у спорах — наприклад, коли інші спадкоємці заперечують підстави. Про те, як частки співвідносяться з правами того з подружжя, хто пережив, читайте у статті <a href="/blog/spadkuvannya-podruzhzhyam/">про спадкування подружжям</a>.</p>`,
