        id: "s1",
        h2: "Що таке обов'язкова частка у спадщині",
        html: `<p>Свобода заповіту в Україні не абсолютна. Навіть якщо спадкодавець заповів усе майно одній особі, закон гарантує окремим членам родини частину спадщини — <strong>обов'язкову частку</strong> (стаття 1241 Цивільного кодексу України). Це механізм захисту найвразливіших спадкоємців, які об'єктивно не можуть себе забезпечити.</p>
<p>Обов'язкова частка діє лише тоді, коли є заповіт, який позбавляє таких осіб спадщини або зменшує їхню частку. Якщо заповіту немає, спадкування відбувається за законом у порядку черг — про це наш окремий розбір <a href="/blog/cherhy-spadkuvannya-za-zakonom/">про черги спадкування</a>, і поняття обов'язкової частки тоді не застосовується.</p>`,
