<li><strong>Порівняйте актив і пасив.</strong> Якщо борги явно перевищують вартість майна — розгляньте <a href="/blog/vidmova-vid-spadshchyny/">відмову від спадщини</a>: строк на неї той самий, шість місяців.</li>
