        html: `<p>Квартира, придбана за час шлюбу, є спільною сумісною власністю подружжя (стаття 60 Сімейного кодексу України) — навіть якщо кредитний договір оформлено на одного, а другий ніде не фігурує. Дзеркальне правило діє і щодо боргу: зобов'язання, взяте в інтересах сім'ї, покладається на обох (стаття 65 СК України).</p>
<p>Тому «поділ іпотечної квартири» — це завжди поділ двох речей одночасно: активу (права власності) та пасиву (залишку кредиту). Поділити квартиру навпіл і лишити весь борг на одному — так само неправильно, як і навпаки. Загальні правила поділу ми розібрали на сторінці послуги <a href="/practices/family-law/podil-spilnoho-mayna-podruzhzhya/">«Поділ спільного майна подружжя»</a>.</p>`,
