        h2: "Хто може скласти заповіт і що в нього включити",
        html: `<p>Заповіт — це особисте розпорядження фізичної особи на випадок своєї смерті (стаття 1233 Цивільного кодексу України). Скласти його може особа з повною цивільною дієздатністю, і лише <strong>особисто</strong> — представництво через довірену особу закон прямо забороняє.</p>
<p>Заповісти можна все майно або його частину, включно з майном, яке заповідач набуде в майбутньому. Спадкоємцями можна призначити будь-кого: родичів, сторонніх осіб, юридичних осіб — родинні зв'язки не обов'язкові. Можна також позбавити спадщини будь-кого зі спадкоємців за законом без пояснення причин (з одним винятком, про який нижче).</p>`,
