        h2: "Чи можна розлучитися, якщо чоловік служить",
        html: `<p>Так. Проходження військової служби не є перешкодою для розірвання шлюбу і не дає жодній зі сторін права заблокувати процес. Закон не містить норми, яка забороняла б розлучення з військовослужбовцем або зупиняла провадження на час служби.</p>
<p>Але процедура має особливості, і вони стосуються не права, а <b>техніки процесу</b>: як повідомити сторону, як забезпечити її участь, як вручити рішення. Саме тут виникають затримки.</p>
<p>Загальний порядок розірвання шлюбу ми розбираємо в матеріалі про <a href="/blog/rozirvannya-shlyubu/">розірвання шлюбу</a> — нижче лише те, що відрізняється.</p>`,
