        id: "s6",
        h2: "Наслідки поновлення",
        html: `<p>Після набрання рішенням законної сили батьківські права відновлюються в повному обсязі: право на виховання, спілкування, представництво інтересів дитини, а також взаємні спадкові права.</p>
<p>Відновлюються й обов’язки — насамперед обов’язок утримувати дитину. Заборгованість за аліментами, що виникла раніше, поновленням прав не скасовується.</p>
<p>Питання про повернення дитини вирішується окремо, з урахуванням її інтересів. Поновлення у правах не означає автоматичного передання дитини — місце проживання визначається за загальними правилами, про які ми пишемо у матеріалі про <a href="/blog/viznachennya-mistsya-prozhyvannya-dytyny/">визначення місця проживання дитини</a>.</p>
<p>Адвокати практики <a href="/practices/family-law/">сімейного права LEGIUS</a> супроводжують справи про поновлення батьківських прав — від формування доказової бази до взаємодії з органом опіки.</p>`,
